import requests
from bs4 import BeautifulSoup
url='https://ebtl.earth/'
html=requests.get(url,timeout=20).text
print('HTML_LENGTH', len(html))
for token in ['latitude','longitude','coords','map','geo','iframe','img','krishnagiri']:
    if token.lower() in html.lower():
        print('FOUND', token)
soup=BeautifulSoup(html,'html.parser')
print('TITLE', soup.title.get_text(strip=True) if soup.title else '')
for tag in soup.find_all(['img','iframe','script','meta']):
    attrs={k:v for k,v in tag.attrs.items() if k in ['src','content','name','property','alt']}
    if any(x in str(attrs).lower() for x in ['map','geo','latitude','longitude','krishnagiri']):
        print(tag.name, attrs)
